const body = $input.first().json.body || $input.first().json;
const clientes = Array.isArray(body.clientes) ? body.clientes : [body];

return clientes.map((cliente, index) => ({
  json: {
    id: cliente.id || `CLI-${index + 1}`,
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    saldo_formatado: cliente.saldo_formatado || `R$ ${cliente.saldo}`,
    perfil: cliente.perfil
  }
}));

const catalogo = [
  { perfil: 'Conservador', produto: 'Poupança', minimo: 100, rentabilidade: '6.2%' },
  { perfil: 'Conservador', produto: 'CDB Liquidez Diária', minimo: 1000, rentabilidade: '12.5%' },
  { perfil: 'Conservador', produto: 'Tesouro Selic', minimo: 500, rentabilidade: '13.0%' },
  { perfil: 'Moderado', produto: 'CDB Prefixado', minimo: 1000, rentabilidade: '14.0%' },
  { perfil: 'Moderado', produto: 'Fundo Multimercado', minimo: 5000, rentabilidade: '16.0%' },
  { perfil: 'Moderado', produto: 'Tesouro IPCA+', minimo: 1000, rentabilidade: 'IPCA+6.0%' },
  { perfil: 'Arrojado', produto: 'Ações ETF', minimo: 500, rentabilidade: 'Variável' },
  { perfil: 'Arrojado', produto: 'Fundo de Ações', minimo: 10000, rentabilidade: 'Variável' },
  { perfil: 'Arrojado', produto: 'Criptomoedas', minimo: 100, rentabilidade: 'Variável' }
];

const items = $input.all();
return items.map(item => {
  const c = item.json;
  const produtosPerfil = catalogo.filter(p => p.perfil.toLowerCase() === c.perfil.toLowerCase());
  const produtosAcessiveis = produtosPerfil.filter(p => c.saldo >= p.minimo);
  const produtosFuturos = produtosPerfil.filter(p => c.saldo < p.minimo);

  const promptContexto = `Cliente: ${c.nome}\nPerfil: ${c.perfil}\nSaldo Disponível: ${c.saldo_formatado}\nOpções Compatíveis Acessíveis Imediatamente: ${produtosAcessiveis.map(p => p.produto + ' (Mín: R$' + p.minimo + ', Rent: ' + p.rentabilidade + ')').join('; ')}\nOpções para Próximo Aporte: ${produtosFuturos.map(p => p.produto + ' (Mín: R$' + p.minimo + ')').join('; ')}`;

  return {
    json: {
      ...c,
      promptContexto,
      produtosAcessiveis,
      produtosFuturos
    }
  };
});

